"""Dependency-free pages for local setup and analysis."""

BASE = '''<style>:root{--bg:#0b1020;--panel:#151d32;--line:#2c3a5c;--text:#edf2ff;--muted:#aab5ca;--cyan:#54d5ff;--warn:#f6c967;--bad:#ff7285}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px system-ui}.shell{width:min(1100px,94vw);margin:auto;padding:36px 0 70px}.nav{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:20px}.brand{font-size:28px;font-weight:800}.nav a{color:var(--cyan);margin-left:18px}.eyebrow{color:var(--cyan);text-transform:uppercase;letter-spacing:.12em;font-size:12px}.panel,.card{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:22px;margin-top:22px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.card{margin:0;text-decoration:none;color:var(--text);min-height:150px}.card:hover{border-color:var(--cyan)}.card h2{margin:8px 0}.muted{color:var(--muted)}label{display:block;margin:16px 0 6px}input,textarea,button{font:inherit;border-radius:8px;border:1px solid #3e5079;background:#10192d;color:var(--text);padding:10px;width:100%}textarea{min-height:82px;resize:vertical}button{width:auto;background:var(--cyan);color:#07111f;font-weight:700;cursor:pointer}button.secondary{background:#1d2b48;color:var(--text)}button:disabled{opacity:.5;cursor:not-allowed}.row{display:flex;gap:10px;align-items:center}.row input{flex:1}.check{display:flex;gap:8px;align-items:center;margin:10px 0}.check input{width:auto}.errors{color:#ffb1ba;white-space:pre-line}.ok{color:#86e8ad}.logs{background:#09101f;border-radius:9px;padding:14px;min-height:180px;max-height:360px;overflow:auto;font:13px ui-monospace,monospace;white-space:pre-wrap}.status{display:inline-block;border-radius:99px;padding:4px 9px;background:#203354;color:var(--cyan);text-transform:capitalize}.actions{display:flex;gap:10px;margin-top:20px}@media(max-width:700px){.grid{grid-template-columns:1fr}.nav{display:block}.nav div:last-child{margin-top:12px}.nav a{margin:0 16px 0 0}}</style>'''
NAV = '<nav class="nav"><div><div class="eyebrow">Local DJ library intelligence</div><div class="brand">CrateIQ</div></div><div><a href="/">Home</a><a href="/setup">Setup</a><a href="/analysis">Analysis</a><a href="/tracks">Tracks</a><a href="/playlists">Playlists</a></div></nav>'

HOME_HTML = f'''<!doctype html><title>CrateIQ</title>{BASE}<main class="shell">{NAV}<section class="panel"><div class="eyebrow">Welcome</div><h1>Your DJ library, ready for better decisions.</h1><p class="muted">Configure CrateIQ once, run local analysis when you choose, then explore tracks and playlists.</p><div id="state"></div></section><section class="grid"><a class="card" href="/setup"><div class="eyebrow">01</div><h2>Setup</h2><p class="muted">Music folders, Rekordbox XML, formats, and processing preferences.</p></a><a class="card" href="/analysis"><div class="eyebrow">02</div><h2>Analysis</h2><p class="muted">Choose modules for one local run and follow progress live.</p></a><a class="card" href="/tracks"><div class="eyebrow">03</div><h2>Track analysis</h2><p class="muted">Inspect phrases, energy, waveforms, and similar segments.</p></a><a class="card" href="/playlists"><div class="eyebrow">04</div><h2>Playlists</h2><p class="muted">Review playlist flow and manage playable segments.</p></a></section></main><script>fetch('/api/setup').then(r=>r.json()).then(x=>document.getElementById('state').innerHTML=x.configured?'<p class="ok">Setup is complete. You can start analysis whenever you are ready.</p>':'<p class="errors">Setup is required before analysis. Add your music folders to continue.</p>')</script>'''

SETUP_HTML = f'''<!doctype html><title>CrateIQ Setup</title>{BASE}<main class="shell">{NAV}<section class="panel"><div class="eyebrow">First-run setup</div><h1>Tell CrateIQ where your library lives.</h1><p class="muted">Paths stay on this computer in local configuration; they are never part of the shared project.</p><label>Music folders <span class="muted">(one path per line)</span></label><textarea id="roots" placeholder="/Users/you/Music"></textarea><label>Rekordbox XML export <span class="muted">(optional)</span></label><input id="xml" placeholder="/path/to/rekordbox.xml"><label>Output location</label><input id="output"><label>Analysis workers</label><input id="workers" type="number" min="1"><details><summary>Advanced processing settings</summary><label>Supported formats <span class="muted">(comma-separated)</span></label><input id="formats"><div id="modules"></div></details><div id="message"></div><div class="actions"><button id="validate" class="secondary">Validate paths</button><button id="save">Save setup</button></div></section></main><script>const $=id=>document.getElementById(id),names={{metadata:'Metadata',rekordbox_library:'Rekordbox library',rekordbox_analysis:'Rekordbox analysis',energy:'Energy',fingerprint:'Fingerprints'}};let current;function read(){{return {{musicRoots:$('roots').value.split('\\n'),rekordboxXmlPath:$('xml').value,outputRoot:$('output').value,analysisWorkers:+$('workers').value,supportedFormats:$('formats').value.split(','),modules:Object.fromEntries(Object.keys(names).map(k=>[k,$('module-'+k).checked]))}}}}function fill(c){{current=c;$('roots').value=(c.musicRoots||[]).join('\\n');$('xml').value=c.rekordboxXmlPath||'';$('output').value=c.outputRoot;$('workers').value=c.analysisWorkers;$('formats').value=c.supportedFormats.join(', ');$('modules').innerHTML='<label>Modules for the default Full Rekordbox setup</label>'+Object.entries(names).map(([k,n])=>`<label class="check"><input id="module-${{k}}" type="checkbox" ${{c.modules[k]?'checked':''}}>${{n}}</label>`).join('')}}function show(x){{$('message').innerHTML=x.valid?'<p class="ok">Paths are valid.</p>':`<p class="errors">${{x.errors.join('\\n')}}</p>`}}async function action(url){{let r=await fetch(url,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(read())}}),x=await r.json();show(x);if(url.endsWith('/save')&&x.valid)setTimeout(()=>location='/',500)}}fetch('/api/setup').then(r=>r.json()).then(x=>fill(x.config));$('validate').onclick=()=>action('/api/setup/validate');$('save').onclick=()=>action('/api/setup/save');</script>'''

ANALYSIS_HTML = f'''<!doctype html><title>CrateIQ Analysis</title>{BASE}<main class="shell">{NAV}<section class="panel"><div class="eyebrow">Local analysis</div><h1>Run analysis on your terms.</h1><div id="config" class="muted"></div><div id="modules"></div><div class="actions"><button id="start">Start analysis</button><button id="stop" class="secondary">Stop safely</button></div><p>Status: <span id="status" class="status">loading</span></p><div id="logs" class="logs"></div><p id="result"></p></section></main><script>const $=id=>document.getElementById(id),names={{metadata:'Metadata',rekordbox_library:'Rekordbox library',rekordbox_analysis:'Rekordbox analysis',energy:'Energy',fingerprint:'Fingerprints'}};let config;function selection(){{return Object.fromEntries(Object.keys(names).map(k=>[k,$('module-'+k).checked]))}}function renderSetup(x){{config=x.config;$('config').textContent=x.configured?`${{config.musicRoots.length}} music folder(s) · output: ${{config.outputRoot}}`:'Complete Setup before starting analysis.';$('start').disabled=!x.configured;$('modules').innerHTML='<h3>This run only</h3>'+Object.entries(names).map(([k,n])=>`<label class="check"><input id="module-${{k}}" type="checkbox" ${{config.modules[k]?'checked':''}}>${{n}}</label>`).join('')}}async function poll(){{let x=await fetch('/api/analysis/status').then(r=>r.json());$('status').textContent=x.status;$('logs').textContent=(x.events||[]).map(e=>`[${{e.stage}}] ${{e.message}}`).join('\\n');$('result').textContent=x.error|| (x.result?`Finished: ${{x.result.tracks||0}} tracks processed.`:'');$('stop').disabled!==['running','stopping'].includes(x.status);setTimeout(poll,1000)}}fetch('/api/setup').then(r=>r.json()).then(renderSetup);$('start').onclick=async()=>{{let x=await fetch('/api/analysis/start',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{modules:selection()}})}}).then(r=>r.json());if(x.error)alert(x.error)}};$('stop').onclick=()=>fetch('/api/analysis/stop',{{method:'POST'}});poll();</script>'''

# Keep the generated page readable while correcting the stop-control state assignment.
ANALYSIS_HTML = ANALYSIS_HTML.replace("$('stop').disabled!==['running','stopping'].includes(x.status)", "$('stop').disabled=!['running','stopping'].includes(x.status)")
